// [Barber Demo] Availability Calculator (GHL free-slots backend)
var webhookBody = $('Webhook - Check Availability').first().json.body;
var preferredDate = webhookBody.date;
var resp = $input.first().json;
var dayData = resp[preferredDate];
var isoSlots = (dayData && dayData.slots) || [];
function toDisplay(iso) {
  var timePart = iso.split('T')[1].substring(0, 5);
  var hh = parseInt(timePart.substring(0, 2), 10);
  var mm = timePart.substring(3, 5);
  var dispHour = hh > 12 ? hh - 12 : (hh === 0 ? 12 : hh);
  var ampm = hh >= 12 ? 'PM' : 'AM';
  return { display: dispHour + ':' + mm + ' ' + ampm, start: iso };
}
var slots = isoSlots.map(toDisplay);
return [{ json: {
  available_slots: slots,
  date: preferredDate,
  count: slots.length,
  message: slots.length === 0
    ? 'No availability found on ' + preferredDate + '. Please ask the caller to suggest another date.'
    : 'Available times on ' + preferredDate + ': ' + slots.slice(0, 3).map(function(s) { return s.display; }).join(', ') + (slots.length > 3 ? ' and more.' : '.')
} }];

// [Barber Demo] Prepare GHL appointment payload
var body = $('Webhook - Book Appointment').first().json.body;
var start = body.slot;
var d = new Date(start);
var endD = new Date(d.getTime() + 30 * 60000);
var end = endD.toISOString();
var contactUpsert = $('GHL Upsert Contact').first().json;
var contactId = (contactUpsert && contactUpsert.contact) ? contactUpsert.contact.id : null;
var notes = 'Rise AI Demo Booking (Northbridge Barbers)\n\n'
  + 'Name: ' + body.name + '\n'
  + 'Phone: ' + body.phone + '\n'
  + 'Service: ' + body.service + '\n'
  + 'Requested slot: ' + start
  + (body.notes ? ('\nNotes: ' + body.notes) : '')
  + '\n\nBooked via The Rise AI barber demo phone receptionist. DEMO CALENDAR — not a live diary.';
return [{ json: {
  calendarId: '<CALENDAR_ID>',
  locationId: '<LOCATION_ID>',
  contactId: contactId,
  startTime: start,
  endTime: end,
  title: '[Barber Demo] ' + body.name + ' \u2014 ' + body.service,
  notes: notes,
  appointmentStatus: 'confirmed',
  ignoreFreeSlotValidation: true
} }];

var d = $('Webhook - Book Appointment').first().json.body;
var confirmation = 'Booking confirmed! ' + d.name + ' is booked for a ' + d.service + ' at ' + d.slot + '.';
confirmation += ' Our team has been notified.';
return [{ json: { success: true, confirmation: confirmation } }];

// [Barber Demo] Match the search result against the caller's provided phone (digit-normalized).
var providedPhone = $('Webhook - Find Appointment').first().json.body.phone;
function digits(s) { return (s || '').replace(/\D/g, ''); }
var providedDigits = digits(providedPhone);
var resp = $input.first().json;
var contacts = resp.contacts || (resp.contact ? [resp.contact] : []) || [];
var match = contacts.find(function(c) {
  var cd = digits(c.phone);
  return cd.length >= 8 && providedDigits.length >= 8 && cd.slice(-9) === providedDigits.slice(-9);
});
if (!match && contacts.length === 1) match = contacts[0];
var found = !!match;
return [{ json: {
  found: found,
  contactId: found ? match.id : null,
  contact_name: found ? (match.contactName || match.name || ((match.firstName || '') + ' ' + (match.lastName || '')).trim()) : null
} }];

// [Barber Demo] Keep only this caller's upcoming, non-cancelled appointments on the demo calendar.
var target = $('Extract Contact').first().json;
var items = $input.all();
var now = Date.now();
function fmt(iso) {
  try {
    return new Intl.DateTimeFormat('en-AU', { timeZone: 'Australia/Perth', weekday: 'short', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true }).format(new Date(iso));
  } catch (e) { return iso; }
}
var matches = [];
for (var i = 0; i < items.length; i++) {
  var raw = items[i].json;
  var ev = raw.appointment || raw.event || raw;
  var status = String(ev.appointmentStatus || ev.status || '').toLowerCase();
  var evContactId = ev.contactId || (ev.contact && ev.contact.id) || null;
  var startIso = ev.startTime || ev.start;
  if (!ev.id || evContactId !== target.contactId) continue;
  if (status === 'cancelled') continue;
  if (startIso && new Date(startIso).getTime() < now) continue;
  var title = ev.title || '';
  var svcMatch = /\u2014\s*(.+)$/.exec(title);
  var noteMatch = ev.notes ? /Service:\s*(.+)/.exec(ev.notes) : null;
  var service = svcMatch ? svcMatch[1].trim() : (noteMatch ? noteMatch[1].trim() : 'appointment');
  matches.push({ id: ev.id, start: startIso, display: fmt(startIso), service: service, contact_name: target.contact_name });
}
matches.sort(function(a, b) { return new Date(a.start) - new Date(b.start); });
return [{ json: { status: matches.length ? 'found' : 'not_found', appointments: matches } }];

// [Barber Demo] Server-side second phone match against the appointment's contact (defense in depth --
// the agent already checks name+phone conversationally before calling this tool).
var providedPhone = $('Webhook - Cancel Appointment').first().json.body.phone;
function digits(s) { return (s || '').replace(/\D/g, ''); }
var providedDigits = digits(providedPhone);
var rawAppt = $('GHL Get Appointment').first().json;
var appt = rawAppt.appointment || rawAppt.event || rawAppt;
var rawContact = $input.first().json;
var contact = rawContact.contact || rawContact;
var contactDigits = digits(contact.phone);
var matched = providedDigits.length >= 8 && contactDigits.length >= 8 && providedDigits.slice(-9) === contactDigits.slice(-9);
return [{ json: {
  matched: matched,
  appointmentId: appt.id,
  calendarId: appt.calendarId,
  title: appt.title,
  service: (function() { var m = /\u2014\s*(.+)$/.exec(appt.title || ''); return m ? m[1].trim() : 'appointment'; })(),
  startTime: appt.startTime || appt.start
} }];

var p = $('Check Phone Match').first().json;
var confirmation = 'Done -- your ' + p.service + ' has been cancelled.';
return [{ json: { success: true, confirmation: confirmation } }];

// [Barber Demo] Server-side second phone match against the appointment's contact (defense in depth --
// the agent already checks name+phone conversationally before calling this tool).
var providedPhone = $('Webhook - Reschedule Appointment').first().json.body.phone;
function digits(s) { return (s || '').replace(/\D/g, ''); }
var providedDigits = digits(providedPhone);
var rawAppt = $('GHL Get Appointment (Reschedule)').first().json;
var appt = rawAppt.appointment || rawAppt.event || rawAppt;
var rawContact = $input.first().json;
var contact = rawContact.contact || rawContact;
var contactDigits = digits(contact.phone);
var matched = providedDigits.length >= 8 && contactDigits.length >= 8 && providedDigits.slice(-9) === contactDigits.slice(-9);
return [{ json: {
  matched: matched,
  appointmentId: appt.id,
  calendarId: appt.calendarId,
  title: appt.title,
  service: (function() { var m = /\u2014\s*(.+)$/.exec(appt.title || ''); return m ? m[1].trim() : 'appointment'; })(),
  startTime: appt.startTime || appt.start
} }];

var body = $('Webhook - Reschedule Appointment').first().json.body;
var check = $('Check Phone Match (Reschedule)').first().json;
var start = body.new_slot;
var d = new Date(start);
var end = new Date(d.getTime() + 30 * 60000).toISOString();
return [{ json: { appointmentId: check.appointmentId, startTime: start, endTime: end, service: check.service } }];

var p = $('Prepare Reschedule Fields').first().json;
var confirmation = 'Done -- your ' + p.service + ' has been moved to ' + p.startTime + '.';
return [{ json: { success: true, confirmation: confirmation } }];
